    CREATOR_ID     VARCHAR(32)      NULL COMMENT '创建人ID',
    MODIFY_TIME    VARCHAR(20)      NULL COMMENT '修改时间',
    MODIFIER_ID    VARCHAR(32)      NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_MESSAGE_CONTEXT_KEY_LOCALE (TENANT_ID, ORG_ID, MESSAGE_KEY, LOCALE),
    INDEX IDX_MESSAGE_CONTEXT (TENANT_ID, ORG_ID)
) COMMENT='多语言消息表';

-- PEACH_NOTICE.sql
CREATE TABLE PEACH_NOTICE
(
    ID                  VARCHAR(64)  NOT NULL COMMENT '通知ID',
    NOTICE_CODE         VARCHAR(64)  NOT NULL COMMENT '通知编码',
    TITLE_MESSAGE_KEY   VARCHAR(128)     NULL COMMENT '标题消息Key',
    CONTENT_MESSAGE_KEY VARCHAR(128)     NULL COMMENT '内容消息Key',
    NOTICE_TYPE         VARCHAR(32)      NULL COMMENT '通知类型',
    PRIORITY            INT              NULL COMMENT '优先级',
    PUBLISH_STATUS      VARCHAR(32)      NULL COMMENT '发布状态',
    EFFECTIVE_FROM      VARCHAR(20)      NULL COMMENT '生效开始时间',
    EFFECTIVE_TO        VARCHAR(20)      NULL COMMENT '生效结束时间',
    READ_COUNT          INT              NULL COMMENT '阅读次数',
    INBOX_ENABLED       INT              NULL COMMENT '是否启用收件箱',
    STATUS              INT              NULL COMMENT '状态',
    TENANT_ID           VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID              VARCHAR(32)  NOT NULL COMMENT '机构ID',
    CREATED_TIME        VARCHAR(20)      NULL COMMENT '创建时间',
    CREATOR_ID          VARCHAR(32)      NULL COMMENT '创建人ID',
    MODIFY_TIME         VARCHAR(20)      NULL COMMENT '修改时间',
    MODIFIER_ID         VARCHAR(32)      NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_NOTICE_CONTEXT_CODE (TENANT_ID, ORG_ID, NOTICE_CODE),
    INDEX IDX_NOTICE_CONTEXT_STATUS (TENANT_ID, ORG_ID, PUBLISH_STATUS, STATUS)
) COMMENT='通知公告表';

-- PEACH_NOTICE_READ_RECORD.sql
CREATE TABLE PEACH_NOTICE_READ_RECORD
(
    ID            VARCHAR(64) NOT NULL COMMENT '主键ID',
    NOTICE_CODE   VARCHAR(64) NOT NULL COMMENT '通知编码',
    READ_USER_ID  VARCHAR(64) NOT NULL COMMENT '阅读用户ID',
    READ_TIME     VARCHAR(20)     NULL COMMENT '阅读时间',
    TENANT_ID    VARCHAR(32) NOT NULL COMMENT '租户ID',
    ORG_ID       VARCHAR(32) NOT NULL COMMENT '机构ID',
    CREATED_TIME  VARCHAR(20)     NULL COMMENT '创建时间',
    CREATOR_ID    VARCHAR(32)     NULL COMMENT '创建人ID',
    MODIFY_TIME   VARCHAR(20)     NULL COMMENT '修改时间',
    MODIFIER_ID   VARCHAR(32)     NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_NOTICE_READ_CONTEXT (TENANT_ID, ORG_ID, NOTICE_CODE, READ_USER_ID),
    INDEX IDX_NOTICE_READ_CONTEXT_USER (TENANT_ID, ORG_ID, READ_USER_ID)
) COMMENT='通知阅读记录表';

-- PEACH_ORGANIZATION.sql
CREATE TABLE PEACH_ORGANIZATION (
    ORG_ID        VARCHAR(32)  NOT NULL COMMENT '机构ID',
    TENANT_ID     VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_CODE      VARCHAR(64)  NOT NULL COMMENT '机构编码',
    ORG_NAME      VARCHAR(128) NOT NULL COMMENT '机构名称',
    STATUS        VARCHAR(16)  DEFAULT 'ENABLE' COMMENT '状态',
    SORT_NUM      INT          DEFAULT 0 COMMENT '排序',
    IS_DELETE     INT          DEFAULT 0 COMMENT '逻辑删除',
    CREATED_TIME  VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID    VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME   VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID   VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (ORG_ID),
    UNIQUE KEY UK_ORG_CODE (TENANT_ID, ORG_CODE),
    INDEX IDX_ORG_TENANT_ID (TENANT_ID)
);

-- PEACH_RESOURCE.sql
CREATE TABLE PEACH_RESOURCE
(
    RESOURCE_ID      VARCHAR(32)  NOT  NULL COMMENT '资源ID',
    FUNC_CODE        VARCHAR(128)      NULL COMMENT '功能编码',
    RESOURCE_TYPE    VARCHAR(20)       NULL COMMENT '资源类型',
    RESOURCE_CODE    VARCHAR(64)       NULL COMMENT '资源编码',
    RESOURCE_NAME    VARCHAR(32)       NULL COMMENT '资源名称',
    TENANT_ID        VARCHAR(32)  NOT NULL COMMENT '租户ID',
    APP_ID           VARCHAR(32)  NOT NULL COMMENT '应用ID',
    CREATED_TIME     VARCHAR(20)       NULL COMMENT '创建时间',
    CREATOR_ID       VARCHAR(32)       NULL COMMENT '创建人ID',
    MODIFY_TIME      VARCHAR(20)       NULL COMMENT '修改时间',
    MODIFIER_ID      VARCHAR(32)       NULL COMMENT '修改人ID',
    IS_DELETE        TINYINT(1)   DEFAULT 0 COMMENT '是否删除',
    PRIMARY KEY (RESOURCE_ID),
    UNIQUE KEY UK_RESOURCE_TENANT_APP_FUNC_CODE (TENANT_ID, APP_ID, FUNC_CODE, RESOURCE_CODE)
) COMMENT='资源表';

CREATE INDEX RESOURCE_BUSI_IDX
    ON PEACH_RESOURCE (TENANT_ID, APP_ID, FUNC_CODE, RESOURCE_CODE);

-- PEACH_ROLE.sql
CREATE TABLE PEACH_ROLE
(
    ROLE_ID          VARCHAR(32)  NOT NULL COMMENT '角色ID',
    TENANT_ID        VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID           VARCHAR(32)  NOT NULL COMMENT '机构ID',
    ROLE_CODE        VARCHAR(20)  NOT NULL COMMENT '角色编码',
    FISCAL           SMALLINT(4)  NOT NULL COMMENT '年度',
    ROLE_NAME        VARCHAR(64)  NULL COMMENT '角色名称',
    ROLE_DESC        VARCHAR(64)  NULL COMMENT '角色描述',
    ROLE_SCOPE       VARCHAR(20)  NULL COMMENT '角色范围',
    ROLE_TYPE        VARCHAR(20)  NULL COMMENT '角色类型',
    CREATED_TIME     VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID       VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME      VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID      VARCHAR(32)  NULL COMMENT '修改人ID',
    IS_DELETE        TINYINT(1)   DEFAULT 0 NULL COMMENT '是否删除',
    SKIP_URL         VARCHAR(64)  NULL COMMENT '角色登陆跳转',
    PRIMARY KEY (ROLE_ID)
) COMMENT='角色表';

CREATE UNIQUE INDEX UK_ROLE_CODE
    ON PEACH_ROLE (TENANT_ID, ORG_ID, ROLE_CODE, FISCAL);

CREATE INDEX IDX_ROLE_TENANT_ORG
    ON PEACH_ROLE (TENANT_ID, ORG_ID);

-- PEACH_ROUTER.sql
CREATE TABLE PEACH_ROUTER
(
    ROUTER_ID     VARCHAR(64)  NOT NULL COMMENT '主键',
    ROUTER_CODE   VARCHAR(100) NOT NULL COMMENT '路由代码',
    ROUTER_NAME   VARCHAR(100) NOT NULL COMMENT '路由名称',
    ROUTER_URL    VARCHAR(100) NOT NULL COMMENT '路由路径',
    FILE_PATH     VARCHAR(255) NOT NULL COMMENT '文件路径',
    IS_AUTH       TINYINT(1) DEFAULT 1 NOT NULL COMMENT '是否需要授权',
    IS_CACHE      TINYINT(1) DEFAULT 1 NOT NULL COMMENT '是否缓存',
    MODULE_CODE   VARCHAR(10)  NOT NULL COMMENT '模块代码',
    ROUTER_LEVEL  INT(4) NOT NULL COMMENT '路由级次',
    TENANT_ID     VARCHAR(32)  NOT NULL COMMENT '租户ID',
    APP_ID        VARCHAR(32)  NOT NULL COMMENT '应用ID',
    CREATED_TIME  VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID    VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME   VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID   VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (ROUTER_ID),
    UNIQUE KEY UK_ROUTER_TENANT_APP_CODE (TENANT_ID, APP_ID, ROUTER_CODE),
    UNIQUE KEY UK_ROUTER_TENANT_APP_URL (TENANT_ID, APP_ID, ROUTER_URL),
    INDEX IDX_ROUTER_TENANT_APP (TENANT_ID, APP_ID)
) COMMENT='路由管理表';

-- PEACH_SITE_MESSAGE.sql
CREATE TABLE PEACH_SITE_MESSAGE
(
    ID                  VARCHAR(64)  NOT NULL COMMENT '消息ID',
    MESSAGE_CODE        VARCHAR(64)  NOT NULL COMMENT '消息编码',
    RECEIVER_ID         VARCHAR(64)  NOT NULL COMMENT '接收用户ID',
    TITLE_MESSAGE_KEY   VARCHAR(128) NULL COMMENT '标题消息Key',
    CONTENT_MESSAGE_KEY VARCHAR(128) NULL COMMENT '内容消息Key',
    MESSAGE_TYPE        VARCHAR(32)  NULL COMMENT '消息类型',
    SOURCE_TYPE         VARCHAR(32)  NULL COMMENT '来源类型',
    SOURCE_CODE         VARCHAR(64)  NULL COMMENT '来源编码',
    READ_FLAG           INT          NULL COMMENT '是否已读',
    SEND_STATUS         VARCHAR(32)  NULL COMMENT '发送状态',
    TENANT_ID           VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID              VARCHAR(32)  NOT NULL COMMENT '机构ID',
    CREATED_TIME        VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID          VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME         VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID         VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_SITE_MESSAGE_CONTEXT_RECEIVER (TENANT_ID, ORG_ID, MESSAGE_CODE, RECEIVER_ID),
    INDEX IDX_SITE_MESSAGE_CONTEXT_RECEIVER (TENANT_ID, ORG_ID, RECEIVER_ID, READ_FLAG)
) COMMENT='站内消息表';

-- PEACH_STORAGE_INSTANCE.sql
CREATE TABLE PEACH_STORAGE_INSTANCE
(
    INSTANCE_ID          VARCHAR(64)  NOT NULL COMMENT '存储实例ID',
    INSTANCE_NAME        VARCHAR(128) NOT NULL COMMENT '存储实例名称',
    STORE_TYPE           VARCHAR(32)  NOT NULL COMMENT '存储类型',
    ENDPOINT             VARCHAR(512) DEFAULT NULL COMMENT '访问节点地址',
    REGION               VARCHAR(64)  DEFAULT NULL COMMENT '区域',
    BUCKET_NAME          VARCHAR(128) DEFAULT NULL COMMENT '存储桶名称',
    PREFIX               VARCHAR(512) DEFAULT NULL COMMENT '逻辑路径前缀',
    ACCESS_KEY           VARCHAR(256) DEFAULT NULL COMMENT '访问密钥',
    SECRET_KEY           VARCHAR(512) DEFAULT NULL COMMENT '加密后的私密密钥',
    ROOT_PATH            VARCHAR(512) DEFAULT NULL COMMENT '本地存储或NAS存储根路径',
    DOMAIN               VARCHAR(512) DEFAULT NULL COMMENT '公共访问域名',
    PATH_STYLE_ACCESS    TINYINT(1)   NOT NULL DEFAULT 0 COMMENT '是否启用Path Style访问，0否1是',
    PUBLIC_READ          TINYINT(1)   NOT NULL DEFAULT 0 COMMENT '是否允许公共读取，0否1是',
    EXTRA_JSON           JSON         DEFAULT NULL COMMENT '服务商扩展配置JSON',
    ENABLED              TINYINT(1)   NOT NULL DEFAULT 1 COMMENT '是否启用，0禁用1启用',
    BUILT_IN             TINYINT(1)   NOT NULL DEFAULT 0 COMMENT '是否内置，0否1是',
    TENANT_ID            VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID               VARCHAR(32)  NOT NULL COMMENT '机构ID',
    REMARK               VARCHAR(512) DEFAULT NULL COMMENT '备注',
    CREATED_TIME         VARCHAR(20)  DEFAULT NULL COMMENT '创建时间',
    CREATOR_ID           VARCHAR(32)  DEFAULT NULL COMMENT '创建人ID',
    MODIFY_TIME          VARCHAR(20)  DEFAULT NULL COMMENT '修改时间',
    MODIFIER_ID          VARCHAR(32)  DEFAULT NULL COMMENT '修改人ID',
    PRIMARY KEY (INSTANCE_ID),
    UNIQUE KEY UK_STORAGE_INSTANCE_CONTEXT_NAME (TENANT_ID, ORG_ID, INSTANCE_NAME),
    KEY IDX_STORAGE_INSTANCE_CONTEXT_TYPE (TENANT_ID, ORG_ID, STORE_TYPE),
    KEY IDX_STORAGE_INSTANCE_CONTEXT_ENABLE (TENANT_ID, ORG_ID, ENABLED),
    KEY IDX_STORAGE_INSTANCE_CONTEXT_TYPE_ENABLE (TENANT_ID, ORG_ID, STORE_TYPE, ENABLED)
) COMMENT='云存储实例定义表';

-- PEACH_TENANT.sql
CREATE TABLE PEACH_TENANT
(
    TENANT_ID    VARCHAR(32)  NOT NULL COMMENT '租户ID',
    TENANT_CODE  VARCHAR(64)  NOT NULL COMMENT '租户编码',
    TENANT_NAME  VARCHAR(128) NOT NULL COMMENT '租户名称',
    STATUS       VARCHAR(16)  DEFAULT 'ENABLE' COMMENT '状态',
    SORT_NUM     INT          DEFAULT 0 COMMENT '排序',
    IS_DELETE    INT          DEFAULT 0 COMMENT '逻辑删除',
    CREATED_TIME VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID   VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME  VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID  VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (TENANT_ID),
    UNIQUE KEY UK_TENANT_CODE (TENANT_CODE)
) COMMENT='租户表';

-- PEACH_USER.sql
CREATE TABLE PEACH_USER
(
    USER_ID            VARCHAR(32) NOT NULL COMMENT '用户ID',
    USER_CODE          VARCHAR(32) NULL COMMENT '用户账号',
    PASSWORD           VARCHAR(32) NULL COMMENT '用户密码',
    USER_NAME          VARCHAR(50) NULL COMMENT '用户名称',
    IDENTITY_CODE      VARCHAR(30) NULL COMMENT '用户身份证号',
    INVLIDATE          VARCHAR(20) NULL COMMENT '密码失效日期',
    AUTH_MODE          VARCHAR(20) NULL COMMENT '认证方式',
    STATUS             VARCHAR(20) NULL COMMENT '状态',
    UNLOCK_TIME        VARCHAR(20) NULL COMMENT '解锁时间',
    MENU_STYLE         VARCHAR(20) NULL COMMENT '菜单风格',
    MENU_ROLE          VARCHAR(128) NULL COMMENT '菜单角色',
    LASTEST_LOGIN      VARCHAR(20) NULL COMMENT '最近登录时间',
    ERROR_COUNT        VARCHAR(20) NULL COMMENT '密码错误次数',
    START_DATE         VARCHAR(20) NULL COMMENT '有效期开始',
    END_DATE           VARCHAR(20) NULL COMMENT '有效期结束',
    MOBILE_PHONE       VARCHAR(11) NULL COMMENT '手机号',
    EMAIL              VARCHAR(32) NULL COMMENT '邮箱',
    TENANT_ID  VARCHAR(32) NULL COMMENT '租户ID',
    DEFAULT_ORG_ID     VARCHAR(32) NULL COMMENT '默认机构ID',
    CREATED_TIME       VARCHAR(20) NULL COMMENT '创建时间',
    CREATOR_ID         VARCHAR(32) NULL COMMENT '创建人ID',
    MODIFY_TIME        VARCHAR(20) NULL COMMENT '修改时间',
    MODIFIER_ID        VARCHAR(32) NULL COMMENT '修改人ID',
    IS_DELETE          TINYINT(1) DEFAULT 0 COMMENT '是否删除',
    IS_MODIFY          TINYINT(1) DEFAULT 0 COMMENT '密码是否修改',
    PASSWD_MODIFY_TIME VARCHAR(20) NULL COMMENT '密码修改时间',
    PRIMARY KEY (USER_ID),
    UNIQUE KEY UK_USER_CODE (USER_CODE)
) COMMENT='用户信息表';

-- PEACH_USER_ORG.sql
CREATE TABLE PEACH_USER_ORG
(
    ID           VARCHAR(32) NOT NULL COMMENT '主键ID',
    USER_ID      VARCHAR(32) NOT NULL COMMENT '用户ID',
    TENANT_ID    VARCHAR(32) NOT NULL COMMENT '租户ID',
    ORG_ID       VARCHAR(32) NOT NULL COMMENT '机构ID',
    IS_DEFAULT   TINYINT(1) DEFAULT 0 COMMENT '是否默认机构',
    STATUS       VARCHAR(20) NULL COMMENT '状态',
    CREATED_TIME VARCHAR(20) NULL COMMENT '创建时间',
    CREATOR_ID   VARCHAR(32) NULL COMMENT '创建人ID',
    MODIFY_TIME  VARCHAR(20) NULL COMMENT '修改时间',
    MODIFIER_ID  VARCHAR(32) NULL COMMENT '修改人ID',
    IS_DELETE    TINYINT(1) DEFAULT 0 COMMENT '是否删除',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_USER_ORG (TENANT_ID, USER_ID, ORG_ID),
    INDEX IDX_USER_ORG_USER (TENANT_ID, USER_ID),
    INDEX IDX_USER_ORG_ORG (TENANT_ID, ORG_ID)
) COMMENT='用户机构关系表';

-- PEACH_VALUE_SET.sql
CREATE TABLE PEACH_VALUE_SET
(
    ID            VARCHAR(64)  NOT NULL COMMENT '主键ID',
    VALUE_SET_CODE VARCHAR(64) NOT NULL COMMENT '值集编码',
    VALUE_SET_NAME VARCHAR(128) NULL COMMENT '值集名称',
    MODULE_CODE   VARCHAR(64)  NULL COMMENT '模块编码',
    SOURCE_TYPE   VARCHAR(32)  NULL COMMENT '来源类型',
    DESCRIPTION   VARCHAR(500) NULL COMMENT '描述',
    STATUS        INT          NULL COMMENT '状态',
    TENANT_ID     VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID        VARCHAR(32)  NOT NULL COMMENT '机构ID',
    CREATED_TIME  VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID    VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME   VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID   VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_VALUE_SET_CONTEXT_CODE (TENANT_ID, ORG_ID, VALUE_SET_CODE),
    INDEX IDX_VALUE_SET_CONTEXT (TENANT_ID, ORG_ID)
) COMMENT='值集配置表';

-- PEACH_VALUE_SET_ITEM.sql
CREATE TABLE PEACH_VALUE_SET_ITEM
(
    ID            VARCHAR(64)  NOT NULL COMMENT '主键ID',
    VALUE_SET_CODE VARCHAR(64) NOT NULL COMMENT '值集编码',
    ITEM_CODE     VARCHAR(64)  NOT NULL COMMENT '项编码',
    ITEM_VALUE    VARCHAR(255) NULL COMMENT '项值',
    MESSAGE_KEY   VARCHAR(128) NULL COMMENT '国际化Key',
    SOURCE_TYPE   VARCHAR(32)  NULL COMMENT '来源类型',
    SORT_ORDER    INT          NULL COMMENT '排序号',
    STATUS        INT          NULL COMMENT '状态',
    VISIBLE_FLAG  INT          NULL COMMENT '是否可见',
    EXTRA_JSON    TEXT         NULL COMMENT '扩展JSON',
    TENANT_ID     VARCHAR(32)  NOT NULL COMMENT '租户ID',
    ORG_ID        VARCHAR(32)  NOT NULL COMMENT '机构ID',
    CREATED_TIME  VARCHAR(20)  NULL COMMENT '创建时间',
    CREATOR_ID    VARCHAR(32)  NULL COMMENT '创建人ID',
    MODIFY_TIME   VARCHAR(20)  NULL COMMENT '修改时间',
    MODIFIER_ID   VARCHAR(32)  NULL COMMENT '修改人ID',
    PRIMARY KEY (ID),
    UNIQUE KEY UK_VALUE_SET_ITEM_CONTEXT_CODE (TENANT_ID, ORG_ID, VALUE_SET_CODE, ITEM_CODE),
    INDEX IDX_VALUE_SET_ITEM_CONTEXT_SET (TENANT_ID, ORG_ID, VALUE_SET_CODE)
) COMMENT='值集项表';

-- USER_OPER_LOG.sql
-- 用户操作日志表
CREATE TABLE USER_OPER_LOG (
    ID VARCHAR(32) NOT NULL COMMENT '主键',
    OPT_TYPE_CODE VARCHAR(50) COMMENT '操作类型编码',
    MODULE_CODE VARCHAR(50) COMMENT '模块编码',
    CREATOR_CODE VARCHAR(50) COMMENT '创建人编码',
    CREATOR_NAME VARCHAR(100) COMMENT '创建人名称',
    OPT_CONTENT VARCHAR(4000) COMMENT '操作内容',
    CREATE_TIME VARCHAR(20) COMMENT '创建时间',
    OPT_LEVEL VARCHAR(10) COMMENT '操作级别',
    PRIVATE_IP VARCHAR(50) COMMENT '私网IP',
    PUBLIC_IP VARCHAR(50) COMMENT '公网IP',
    DEVICE VARCHAR(200) COMMENT '设备信息',
    BROWSER VARCHAR(200) COMMENT '浏览器信息',
    OS VARCHAR(100) COMMENT '操作系统',
    EXECUTION_TIME BIGINT COMMENT '执行时间（毫秒）',
    IS_SUCCESS VARCHAR(4) COMMENT '是否成功 (Y: 成功, N: 失败)',
    ERROR_MSG VARCHAR(2000) COMMENT '错误信息',
    RESPONSE_DATA TEXT COMMENT '响应数据',
    ROLE_CODE VARCHAR(50) COMMENT '角色编码',
    REQUEST_URI VARCHAR(500) COMMENT '请求路径',
    REQUEST_METHOD VARCHAR(10) COMMENT '请求方式',
    TENANT_ID VARCHAR(32) NOT NULL COMMENT '租户ID',
    ORG_ID VARCHAR(32) NOT NULL COMMENT '机构ID',
    PRIMARY KEY (ID),
    KEY IDX_USER_OPER_LOG_CONTEXT_TIME (TENANT_ID, ORG_ID, CREATE_TIME),
    KEY IDX_USER_OPER_LOG_CONTEXT_CREATOR (TENANT_ID, ORG_ID, CREATOR_CODE)
) COMMENT='用户操作日志表';
